// Analyze the code generation request
const request = body.request;
const context = body.context || {};

// Extract key information
const modType = context.mod_type || 'forge';
const minecraftVersion = context.minecraft_version || '1.20.1';
const expertise = ['java', 'minecraft_modding', modType];

// Determine code type
let codeType = 'class';
if (request.includes('method') || request.includes('function')) {
  codeType = 'method';
} else if (request.includes('event') || request.includes('handler')) {
  codeType = 'event_handler';
} else if (request.includes('item') || request.includes('block')) {
  codeType = 'minecraft_component';
}

return {
  request,
  context,
  modType,
  minecraftVersion,
  expertise,
  codeType,
  enhancedPrompt: buildEnhancedPrompt(request, context, codeType)
};

function buildEnhancedPrompt(req, ctx, type) {
  let prompt = `Generate ${type} for Minecraft ${ctx.minecraft_version || '1.20.1'} ${ctx.mod_type || 'forge'} mod: ${req}`;

  if (ctx.current_project) {
    prompt += `\n\nCurrent Project: ${ctx.current_project.name}`;
    prompt += `\nPackage: ${ctx.current_project.package || 'com.example.mod'}`;
  }

  if (ctx.recent_files && ctx.recent_files.length > 0) {
    prompt += `\n\nRecent Files: ${ctx.recent_files.map(f => f.name).join(', ')}`;
  }

  prompt += `\n\nRequirements:`;
  prompt += `\n- Use proper Java conventions`;
  prompt += `\n- Include necessary imports`;
  prompt += `\n- Add Javadoc comments`;
  prompt += `\n- Follow ${ctx.mod_type || 'forge'} best practices`;
  prompt += `\n- Include error handling`;

  return prompt;
}

// Process the AI response and format it
const aiResponse = JSON.parse(body.choices[0].message.content);

// Extract code blocks if present
const codeBlocks = aiResponse.match(/```[\s\S]*?```/g) || [];
const cleanCode = codeBlocks.map(block => block.replace(/```[a-z]*\n?/, '').replace(/```$/, '')).join('\n\n');

// Generate additional metadata
const metadata = {
  generatedAt: new Date().toISOString(),
  model: 'meta-llama/llama-3.2-3b-instruct:free',
  codeType: '{{1.codeType}}',
  modType: '{{1.modType}}',
  minecraftVersion: '{{1.minecraftVersion}}',
  hasCodeBlocks: codeBlocks.length > 0,
  estimatedLines: cleanCode.split('\n').length
};

return {
  success: true,
  response: aiResponse,
  code: cleanCode,
  codeBlocks: codeBlocks,
  metadata: metadata,
  formattedForIDE: formatForIDE(cleanCode, metadata)
};

function formatForIDE(code, meta) {
  return {
    language: 'java',
    content: code,
    metadata: meta,
    suggestions: generateSuggestions(code, meta)
  };
}

function generateSuggestions(code, meta) {
  const suggestions = [];

  if (code.includes('@Mod')) {
    suggestions.push({
      type: 'info',
      message: 'Consider adding mod dependencies in mods.toml'
    });
  }

  if (code.includes('public class') && !code.includes('extends')) {
    suggestions.push({
      type: 'tip',
      message: 'You might want to extend a base class like BlockBase or ItemBase'
    });
  }

  return suggestions;
}

// Update agent performance metrics
const performance = {
  agentType: 'code_assistant',
  requestId: body.request_id,
  success: true,
  responseTime: responseTime,
  modelUsed: 'meta-llama/llama-3.2-3b-instruct:free',
  codeType: '{{1.codeType}}',
  modType: '{{1.modType}}',
  timestamp: new Date().toISOString()
};

return {
  success: true,
  result: '{{3.formattedForIDE}}',
  performance: performance,
  metadata: '{{3.metadata}}'
};

// Analyze 3D model design request
const request = body.request;
const context = body.context || {};

// Determine model type
let modelType = 'block';
if (request.includes('item') || request.includes('tool')) {
  modelType = 'item';
} else if (request.includes('entity') || request.includes('mob')) {
  modelType = 'entity';
} else if (request.includes('armor') || request.includes('equipment')) {
  modelType = 'armor';
}

// Extract design requirements
const requirements = {
  modelType,
  style: context.style || 'minecraft_vanilla',
  complexity: context.complexity || 'medium',
  animated: request.includes('animated') || request.includes('animation'),
  textured: !request.includes('wireframe')
};

return {
  request,
  context,
  requirements,
  enhancedPrompt: buildModelPrompt(request, requirements)
};

function buildModelPrompt(req, reqs) {
  let prompt = `Design a ${reqs.modelType} for Minecraft: ${req}`;

  prompt += `\n\nDesign Requirements:`;
  prompt += `\n- Model Type: ${reqs.modelType}`;
  prompt += `\n- Style: ${reqs.style}`;
  prompt += `\n- Complexity: ${reqs.complexity}`;
  prompt += `\n- Animated: ${reqs.animated}`;
  prompt += `\n- Textured: ${reqs.textured}`;

  if (reqs.animated) {
    prompt += `\n\nAnimation Requirements:`;
    prompt += `\n- Provide GeckoLib animation setup`;
    prompt += `\n- Include keyframe descriptions`;
    prompt += `\n- Suggest animation timeline`;
  }

  prompt += `\n\nTechnical Requirements:`;
  prompt += `\n- Provide Blockbench modeling steps`;
  prompt += `\n- Include texture mapping guidelines`;
  prompt += `\n- Suggest optimal polygon count`;
  prompt += `\n- Include export settings`;

  return prompt;
}

// Create Blockbench project structure
const aiResponse = JSON.parse(body.choices[0].message.content);
const modelType = '{{1.requirements.modelType}}';

// Generate Blockbench project data
const projectData = {
  name: `AI_Generated_${modelType}_${Date.now()}`,
  format_version: "3.6",
  minecraft_version: "1.20.1",
  meta: {
    format_version: "3.6",
    format: {
      uid: "xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
    },
    model: {
      identifier: `ai_generated_${modelType}`,
      name: `AI Generated ${modelType}`,
      texture_size: [16, 16],
      visible_box_uv: [[0, 0], [16, 16]]
    }
  },
  elements: generateModelElements(modelType, aiResponse),
  outliner: generateOutliner(modelType),
  textures: generateTextures(modelType),
  animations: '{{1.requirements.animated}}' ? generateAnimations(aiResponse) : []
};

return {
  success: true,
  response: aiResponse,
  projectData: projectData,
  blockbenchFile: createBlockbenchFile(projectData),
  modelingSteps: extractModelingSteps(aiResponse),
  textureGuidelines: extractTextureGuidelines(aiResponse)
};

function generateModelElements(type, response) {
  // Parse AI response to extract model structure
  const elements = [];

  if (type === 'block') {
    elements.push({
      name: "cube",
      from: [0, 0, 0],
      to: [16, 16, 16],
      faces: generateCubeFaces()
    });
  } else if (type === 'item') {
    elements.push({
      name: "item_base",
      from: [2, 2, 2],
      to: [14, 14, 14],
      faces: generateCubeFaces()
    });
  }

  return elements;
}

function generateCubeFaces() {
  return {
    north: { uv: [0, 0, 16, 16], texture: "#texture" },
    east: { uv: [0, 0, 16, 16], texture: "#texture" },
    south: { uv: [0, 0, 16, 16], texture: "#texture" },
    west: { uv: [0, 0, 16, 16], texture: "#texture" },
    up: { uv: [0, 0, 16, 16], texture: "#texture" },
    down: { uv: [0, 0, 16, 16], texture: "#texture" }
  };
}

function generateOutliner(type) {
  return [
    {
      name: `ai_generated_${type}`,
      origin: [8, 8, 8],
      color: "#7f7f7f",
      children: []
    }
  ];
}

function generateTextures(type) {
  return [
    {
      uuid: "xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx",
      name: `ai_generated_${type}`,
      path: `textures/item/ai_generated_${type}.png`,
      folder: "item",
      namespace: "mod",
      mode: "bitmap",
      saved: true
    }
  ];
}

function generateAnimations(response) {
  // Extract animation data from AI response
  return [
    {
      name: "animation",
      length: 1.0,
      loop: "hold_on_last_frame",
      anim_time_update: "return this;",
      bones: {
        "ai_generated_model": {
          rotation: [0, 0, 0],
          position: [0, 0, 0],
          scale: [1, 1, 1]
        }
      }
    }
  ];
}

function createBlockbenchFile(data) {
  return JSON.stringify(data, null, 2);
}

function extractModelingSteps(response) {
  // Extract step-by-step modeling instructions
  const steps = [];
  const lines = response.split('\n');

  for (const line of lines) {
    if (line.match(/^\d+\./) || line.includes('Step')) {
      steps.push(line.trim());
    }
  }

  return steps;
}

function extractTextureGuidelines(response) {
  // Extract texture design guidelines
  const guidelines = [];
  const lines = response.split('\n');

  for (const line of lines) {
    if (line.includes('texture') || line.includes('UV') || line.includes('material')) {
      guidelines.push(line.trim());
    }
  }

  return guidelines;
}

// Analyze build and deployment request
const request = body.request;
const context = body.context || {};

const buildConfig = {
  projectPath: context.project_path || './src',
  buildType: request.includes('deploy') ? 'deploy' : 'build',
  target: request.includes('server') ? 'server' : 'client',
  environment: request.includes('prod') ? 'production' : 'development',
  framework: context.framework || 'forge'
};

return {
  request,
  context,
  buildConfig,
  buildSteps: generateBuildSteps(buildConfig)
};

function generateBuildSteps(config) {
  const steps = [];

  if (config.framework === 'forge') {
    steps.push('gradlew build');
    steps.push('gradlew jar');
  } else if (config.framework === 'fabric') {
    steps.push('./gradlew build');
    steps.push('./gradlew remapJar');
  }

  if (config.buildType === 'deploy') {
    steps.push('package for deployment');
    steps.push('upload to server');
  }

  return steps;
}

// Process build results and generate report
const buildOutput = body.output;
const buildSuccess = buildOutput.includes('BUILD SUCCESSFUL');

const results = {
  success: buildSuccess,
  output: buildOutput,
  artifacts: extractArtifacts(buildOutput),
  errors: extractErrors(buildOutput),
  warnings: extractWarnings(buildOutput),
  buildTime: new Date().toISOString(),
  deployable: buildSuccess && '{{1.buildConfig.buildType}}' === 'deploy'
};

return {
  success: true,
  results: results,
  nextSteps: generateNextSteps(results)
};

function extractArtifacts(output) {
  const artifacts = [];
  const lines = output.split('\n');

  for (const line of lines) {
    if (line.includes('.jar') || line.includes('build/libs/')) {
      artifacts.push(line.trim());
    }
  }

  return artifacts;
}

function extractErrors(output) {
  const errors = [];
  const lines = output.split('\n');

  for (const line of lines) {
    if (line.includes('ERROR') || line.includes('FAILED')) {
      errors.push(line.trim());
    }
  }

  return errors;
}

function extractWarnings(output) {
  const warnings = [];
  const lines = output.split('\n');

  for (const line of lines) {
    if (line.includes('WARNING') || line.includes('deprecated')) {
      warnings.push(line.trim());
    }
  }

  return warnings;
}

function generateNextSteps(results) {
  const steps = [];

  if (results.success) {
    steps.push('Test the build artifacts');
    steps.push('Deploy to test environment');
    if (results.deployable) {
      steps.push('Deploy to production');
    }
  } else {
    steps.push('Fix build errors');
    steps.push('Re-run build');
  }

  return steps;
}
